CREATE TABLE hrms_workspaces(id TEXT PRIMARY KEY NOT NULL,title TEXT NOT NULL); CREATE TABLE hrms_members(id TEXT PRIMARY KEY NOT NULL,workspace_id TEXT NOT NULL REFERENCES hrms_workspaces(id),owner_id TEXT NOT NULL,employee_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('super_admin','hr_admin','manager','employee','finance','recruiter','auditor')),title TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 1, UNIQUE(workspace_id,owner_id));
